}

// ModerationNukeLimit mirrors `DBModerationNukeLimit` (v3) — el techo de una
// acción vigilada: como mucho `max` veces cada `window_ms`, con castigo propio
// o heredado (`inherit`).
type ModerationNukeLimit struct {
	Enabled    bool                              `bson:"enabled"    json:"enabled"`
	Max        int                               `bson:"max"        json:"max"`
