// AutomodDefaultTimeoutMs es la duración por defecto del tempmute (5 minutos)
// que se aplica cuando la acción de una regla es `delete_timeout`.
const AutomodDefaultTimeoutMs = 5 * 60 * 1000

// ModerationCommandNames es el catálogo de comandos configurables del módulo,
// en orden de dominio: primero los 12 del v2 (sanciones + historial) y después
// los 11 que llegan con el v3 (canal, voz, casos, raid). El seed del documento
// nuevo y el backfill de un documento viejo recorren esta misma lista, así que
// añadir un comando aquí lo siembra en AMBOS caminos.
var ModerationCommandNames = []string{
	"ban",
	"tempban",
	"unban",
	"kick",
	"mute",
	"tempmute",
	"unmute",
	"avisar",
	"infrs",
	"modinf",
	"delinf",
	"delinfs",
	// v3
	"limpiar",
