		return d, verr
	}
	if d.BlockedReason, verr = parseNullableEnum(raw.BlockedReason, flowRunBlockReasonSet, flowRunBlockReasonMsg, "blocked_reason"); verr != nil {
		return d, verr
	}
	if d.BranchID, verr = parseNullableBoundedString(raw.BranchID, "branch_id", 1, 64); verr != nil {
		return d, verr
	}
	if d.StepsTotal, verr = parseOptionalNonNegInt(raw.StepsTotal, "steps_total"); verr != nil {
		return d, verr
	}
	if d.StepsRun, verr = parseOptionalNonNegInt(raw.StepsRun, "steps_run"); verr != nil {
		return d, verr
	}
	if d.DurationMs, verr = parseOptionalNonNegInt(raw.DurationMs, "duration_ms"); verr != nil {
		return d, verr
	}
	if d.ErrorCode, verr = parseNullableBoundedString(raw.ErrorCode, "error_code", 1, 128); verr != nil {
		return d, verr
	}
	if d.UserID, verr = parseNullableBoundedString(raw.UserID, "user_id", 1, 32); verr != nil {
		return d, verr
	}
	if d.ChannelID, verr = parseNullableBoundedString(raw.ChannelID, "channel_id", 1, 32); verr != nil {
		return d, verr
	}
	if d.Metadata, verr = parseNullableRecord(raw.Metadata, "metadata"); verr != nil {
		return d, verr
	}
	return d, nil
}

// ─── GET /moderation/flow-runs (list) ─────────────────────────────────────

// ParseFlowRunListQuery mirrors los filtros de listado. `limit` reusa
// coerceTrackErrorLimit (default 50 aplicado por el repo, tope 200 aquí,
// idéntico al contrato); `created_after` es INCLUSIVO en el repo
// (`created_at >= $n`).
func ParseFlowRunListQuery(botID, guildID, flowID, status, createdAfter, limitRaw, offsetRaw string) (dbflowrun.ListParams, *apierrors.CustomError) {
	var p dbflowrun.ListParams
	if botID != "" {
		v := botID
		p.BotID = &v
	}
	if guildID != "" {
		v := guildID
		p.GuildID = &v
	}
	if flowID != "" {
		v := flowID
		p.FlowID = &v
	}
	if status != "" {
		if !flowRunStatusSet[status] {
			return p, zodItemError(flowRunStatusMsg, "status")
		}
		v := status
		p.Status = &v
	}
	if createdAfter != "" {
		if !flowRunOffsetDateTimeRe.MatchString(createdAfter) {
			return p, zodItemError("Invalid ISO datetime", "created_after")
		}
		v := createdAfter
		p.CreatedAfter = &v
	}
	limitPtr, verr := coerceTrackErrorLimit(limitRaw)
	if verr != nil {
		return p, verr
	}
	p.Limit = limitPtr
	offsetPtr, verr := coerceOffset(offsetRaw)
	if verr != nil {
		return p, verr
	}
	p.Offset = offsetPtr
	return p, nil
}

// ─── POST /moderation/flow-runs/blocks (bump) ─────────────────────────────

// ParseFlowRunBumpBlocks mirrors `{bot_id, guild_id, flow_id,
// increments:[{reason,bucket,count}]}`. `increments` requiere al menos un
// elemento; cada uno valida en orden reason → bucket → count, con el índice
// en la property (`increments.0.reason`) para que el primer fallo señale la
// fila exacta.
func ParseFlowRunBumpBlocks(body []byte) (dbflowrun.BumpBlocksData, *apierrors.CustomError) {
	var raw struct {
		BotID      json.RawMessage `json:"bot_id"`
		GuildID    json.RawMessage `json:"guild_id"`
		FlowID     json.RawMessage `json:"flow_id"`
		Increments []struct {
			Reason json.RawMessage `json:"reason"`
			Bucket json.RawMessage `json:"bucket"`
			Count  json.RawMessage `json:"count"`
		} `json:"increments"`
	}
	if err := json.Unmarshal(body, &raw); err != nil {
		return dbflowrun.BumpBlocksData{}, bodyBindError(err)
	}
	var d dbflowrun.BumpBlocksData
	var verr *apierrors.CustomError
	if d.BotID, verr = parseRequiredString(raw.BotID, "bot_id", 1, 32); verr != nil {
		return d, verr
	}
	if d.GuildID, verr = parseRequiredString(raw.GuildID, "guild_id", 1, 32); verr != nil {
		return d, verr
	}
	if d.FlowID, verr = parseRequiredString(raw.FlowID, "flow_id", 1, 64); verr != nil {
		return d, verr
	}
	if len(raw.Increments) == 0 {
		return d, zodItemError("Too small: expected array to have >=1 items", "increments")
	}
	d.Increments = make([]dbflowrun.BlockIncrement, 0, len(raw.Increments))
	for i, inc := range raw.Increments {
		prefix := "increments." + strconv.Itoa(i) + "."
		reason, rerr := parseEnumRequired(inc.Reason, flowRunBlockReasonSet, flowRunBlockReasonMsg, prefix+"reason")
		if rerr != nil {
			return d, rerr
		}
		bucket, berr := parseRequiredOffsetDatetime(inc.Bucket, prefix+"bucket")
		if berr != nil {
			return d, berr
		}
		count, cerr := parseRequiredInt(inc.Count, prefix+"count", 0, 0)
		if cerr != nil {
			return d, cerr
		}
		d.Increments = append(d.Increments, dbflowrun.BlockIncrement{Reason: reason, Bucket: bucket, Count: int64(count)})
	}
	return d, nil
}

// ─── GET /moderation/flow-runs/blocks ─────────────────────────────────────

// ParseFlowRunBlocksQuery mirrors `?bot_id&guild_id&flow_id&since`. Los
// cuatro son filtros opcionales, igual que el resto de query params del
// servicio (el caller de verdad —RunsPanel— los manda siempre, pero la capa
// de validación no lo exige, mismo criterio que dbinfraction.ListParams).
func ParseFlowRunBlocksQuery(botID, guildID, flowID, since string) (dbflowrun.BlocksParams, *apierrors.CustomError) {
	var p dbflowrun.BlocksParams
	if botID != "" {
		v := botID
